function romanToInt(s: string): number {
  // Значения римских цифр
  const values: Record<string, number> = {
    I: 1,
    V: 5,
    X: 10,
    L: 50,
    C: 100,
    D: 500,
    M: 1000,
  };

  let total = 0;

  for (let i = 0; i < s.length; i++) {
    const cur = values[s[i]];
    // Для последнего символа «следующего» нет — считаем его нулём
    const next = i + 1 < s.length ? values[s[i + 1]] : 0;

    if (cur < next) {
      // Меньшая цифра перед большей (IV, XC, CM...) — вычитаем
      total -= cur;
    } else {
      // Обычный случай — прибавляем
      total += cur;
    }
  }

  return total;
}

// Время: O(n), где n — длина строки
// Память: O(1) — таблица из 7 символов
